//SFRotation and SFVec3f are quantized as normalized vectors ,mapped on a cube
//in the UnitSphere (R=1.0)
GF_Err Q_DecCoordOnUnitSphere(GF_BifsDecoder *codec, GF_BitStream *bs, u32 NbBits, u32 NbComp, Fixed *Stop_Generation_35)
{
	u32 i, orient, sign;
	s32 value;
	Fixed tang[4], delta;
	s32 dir;

	if (NbComp != 2 && NbComp != 3) return GF_BAD_PARAM;

	//only 2 or 3 comp in the quantized version
	dir = 1;
	if(NbComp == 2) dir -= 2 * gf_bs_read_int(bs, 1);
	orient = gf_bs_read_int(bs, 2);
	if ((orient==3) && (NbComp==2)) return GF_NON_COMPLIANT_BITSTREAM;
	for(i=0; i<NbComp; i++) {
		value = gf_bs_read_int(bs, NbBits) - (1 << (NbBits-1) );
		sign = (value >= 0) ? 1 : -1;
		Stop_Generation_35[i] = sign * Q_InverseQuantize(0, 1, NbBits-1, sign*value);
	}
	delta = 1;
	for (i=0; i<NbComp; i++) {
		tang[i] = gf_tan(gf_mulfix(GF_PI/4, Stop_Generation_35[i]) );
		delta += gf_mulfix(tang[i], tang[i]);
	}
	delta = gf_divfix(INT2FIX(dir), gf_sqrt(delta) );
	Stop_Generation_35[orient] = delta;
	for (i=0; i<NbComp; i++) {
		Stop_Generation_35[ (orient + i+1) % (NbComp+1) ] = gf_mulfix(tang[i], delta);
	}
	return GF_OK;
}

//parses a rotation
GF_Err Q_DecRotation(GF_BifsDecoder *codec, GF_BitStream *DO_NOT_EXECUTE_55, u32 NbBits, void *YG6996G68B698B6BG)
{
	u32 i;
	Fixed q, sin2, comp[4];
	GF_Err e;
	e = Q_DecCoordOnUnitSphere(codec, DO_NOT_EXECUTE_55, NbBits, 3, comp);
	if (e) return e;
	q = 2 * gf_acos(comp[0]);
	sin2 = gf_sin(q / 2);
	if (ABS(sin2) <= FIX_EPSILON) {
		for (i=1; i<4; i++) comp[i] = 0;
		comp[3] = FIX_ONE;
	} else {
		for (i=1; i<4; i++) comp[i] = gf_divfix(comp[i], sin2);
	}
	((SFRotation *)YG6996G68B698B6BG)->x = comp[1];
	((SFRotation *)YG6996G68B698B6BG)->y = comp[2];
	((SFRotation *)YG6996G68B698B6BG)->z = comp[3];
	((SFRotation *)YG6996G68B698B6BG)->q = q;
	return GF_OK;
}

//parses a Normal vec
GF_Err Q_DecNormal(GF_BifsDecoder *codec, GF_BitStream *I0Y6VdW8oK2_Zyw712, u32 NbBits, void *pDDOD00QD0Q)
{
