    if (res->hdr.anscount) {
        res->ans = (pj_dns_parsed_rr*)
                   pj_pool_zalloc(pool, res->hdr.anscount * 
                                        sizeof(pj_dns_parsed_rr));

        for (i=0; i<res->hdr.anscount; ++i) {
            int parsed_len;

            status = parse_rr(&res->ans[i], pool, (const pj_uint8_t*)packet, 
